    'help.faq.001.q': '如何开始一段对话？',
    'help.faq.001.a': '打开对话并选择“新对话”或某个起始提示。',
    'help.faq.002.q': '能否在对话中附加文件？',
    'help.faq.002.a': '使用输入框中的附件控件。文件会被扫描、解析并限定在会话范围内。',
    'help.faq.003.q': '为什么发送按钮被禁用？',
    'help.faq.003.a': '实时智能体连接必须就绪，且消息必须包含文本。',
    'help.faq.004.q': '如何暂停智能体运行？',
    'help.faq.004.a': '使用对话工具栏中的“暂停”。当前事件位置会被保留以便恢复。',
    'help.faq.005.q': '审批卡片意味着什么？',
    'help.faq.005.a': '某个工具调用越过了工作区策略边界，需要明确决策。',
    'help.faq.006.q': '在哪里能看到引用？',
    'help.faq.006.a': '使用检索时，接地来源会随助手响应一起出现。',
    'help.faq.007.q': '如何重试失败的响应？',
    'help.faq.007.a': '再次打开对话，在失败的消息或运行上使用重试操作。',
    'help.faq.008.q': '能否导出对话？',
    'help.faq.008.a': '当工作区策略允许时，可从对话创建或分享工件。',
    'help.faq.009.q': '为什么助手说来源不可信？',
    'help.faq.009.a': '外部内容被标记为不可信，使其无法更改系统指令或权限。',
    'help.faq.010.q': '用量限额如何显示？',
    'help.faq.010.a': '对话工具栏显示已用步数与会话预算。',
    'help.faq.011.q': '如何创建知识库？',
    'help.faq.011.a': '打开知识库并选择“新建知识库”，然后添加源文件。',
    'help.faq.012.q': '哪些文件可被索引？',
    'help.faq.012.a': '受支持的格式由 API 校验，不支持的会以明确格式错误拒绝。',
    'help.faq.013.q': '如何查看索引进度？',
    'help.faq.013.a': '知识列表与文档表会显示当前的解析与索引状态。',
    'help.faq.014.q': '能否只搜索单个知识库？',
    'help.faq.014.a': '打开知识库详情视图并使用检索试验场。',
    'help.faq.015.q': '文档如何隔离？',
    'help.faq.015.a': '文档按工作区限定范围，每个检索请求都会针对操作者工作区检查。',
    'help.faq.016.q': '检索试验场有什么用？',
    'help.faq.016.a': '它让您在精确匹配的块用于 AMA 响应接地前进行检查。',
    'help.faq.017.q': '如何移除来源？',
    'help.faq.017.a': '使用文档操作菜单或数据集 API；删除受保留策略约束。',
    'help.faq.018.q': '如何衡量检索质量？',
    'help.faq.018.a': '可从知识库评估运行评估集，随时间比较检索质量。',
    'help.faq.019.q': '能否同步连接器？',
    'help.faq.019.a': '可从 Studio 集成进行连接器设置，带显式范围与投递历史。',
    'help.faq.020.q': '为什么文档被标记为失败？',
    'help.faq.020.a': '文档解析器或恶意软件/格式校验失败；文档错误会被保留以供诊断。',
    'help.faq.021.q': '如何创建工作流？',
    'help.faq.021.a': '打开工作流，定义图谱，并在运行前保存一个版本。',
    'help.faq.022.q': '什么是工作流版本？',
    'help.faq.022.a': '版本冻结运行所使用的图谱与策略相关配置。',
    'help.faq.023.q': '工作流能否等待审批？',
    'help.faq.023.a': '可以。当受治理操作需要审核者时，运行进入待审批状态。',
    'help.faq.024.q': '在哪里查看工作流运行？',
    'help.faq.024.a': '使用工作流运行视图或平台运营查看执行证据。',
    'help.faq.025.q': '重试如何处理？',
    'help.faq.025.a': '可重试的外部工作在 worker 中记录幂等性与重试状态。',
    'help.faq.026.q': '工作流能否调用工具？',
    'help.faq.026.a': '工具可通过配置的能力集使用，并仍受策略检查约束。',
    'help.faq.027.q': '工作流失败时会怎样？',
    'help.faq.027.a': '运行记录状态、错误、追踪数据与运营事件以供诊断。',
    'help.faq.028.q': '能否从工作流发布应用？',
    'help.faq.028.a': 'Studio 应用仅在所需审查与版本检查通过后才能发布。',
    'help.faq.029.q': '自动化与工作流有何不同？',
    'help.faq.029.a': '自动化按计划或事件触发工作；工作流描述可执行图谱。',
    'help.faq.030.q': '如何停止排队中的运行？',
    'help.faq.030.a': '在 worker 认领执行前，从运行控制界面取消它。',
    'help.faq.031.q': '哪些角色可审批工具调用？',
    'help.faq.031.a': '工作区授权策略决定哪些角色可审批各风险等级。',
    'help.faq.032.q': '审计事件存储在哪里？',
    'help.faq.032.a': '企业审计事件对授权管理员可用，并携带请求上下文。',
    'help.faq.033.q': '如何配置 SSO？',
    'help.faq.033.a': '在控制台打开企业身份并配置允许列表中的身份提供方。',
    'help.faq.034.q': 'API 密钥是否以明文存储？',
    'help.faq.034.a': '不是。密钥被哈希处理，仅在创建时显示一次。',
    'help.faq.035.q': '提供商凭据如何受保护？',
    'help.faq.035.a': '凭据被加密或按引用存储，绝不会在列表响应中返回。',
    'help.faq.036.q': '能否撤销设备会话？',
    'help.faq.036.a': '管理员可在安全与设备中审查并撤销设备会话。',
    'help.faq.037.q': '隐私请求如何运作？',
    'help.faq.037.a': '隐私请求创建带处理步骤与删除墓碑的可审计工作流。',
    'help.faq.038.q': 'WorkAMA 是否用客户内容训练？',
    'help.faq.038.a': '公共平台契约报告客户内容训练为禁用。',
    'help.faq.039.q': '如何报告安全问题？',
    'help.faq.039.a': '使用仓库安全策略中的安全联系方式，并尽可能附上可复现的请求 ID。',
    'help.faq.040.q': '在哪里查看用量与账单？',
    'help.faq.040.a': '网关用量与账单显示当前限额、余额与订阅状态。',
    'help.faq.041.q': '请求 ID 标识什么？',
    'help.faq.041.a': '它链接响应及其运营日志，而不暴露密钥或客户内容。',
    'help.faq.042.q': '如何使用 API？',
    'help.faq.042.a': '阅读 API 文档，创建带范围的凭据，并带工作区授权发送请求。',
    'help.faq.043.q': '是否有 WebSocket 会话 API？',
    'help.faq.043.a': '有。会话票据授权一个会话的短期实时连接。',
    'help.faq.044.q': 'Webhook 如何重试？',
    'help.faq.044.a': '投递状态记录尝试次数、响应码、签名与下次重试时间。',
    'help.faq.045.q': '如何检查网关日志？',
    'help.faq.045.a': '授权操作者可打开网关日志并按通道、状态或请求 ID 过滤。',
    'help.faq.046.q': '状态 operational 是什么意思？',
    'help.faq.046.a': '对应健康端点在检查超时内返回了成功响应。',
    'help.faq.047.q': '如何联系支持？',
    'help.faq.047.a': '使用平台支持入口，附上工作区、请求 ID 与最小复现。',
    'help.faq.048.q': '发布说明在哪里维护？',
    'help.faq.048.a': '仓库发布文档与当前进度追踪器记录已交付的平台变更。',
    'help.faq.049.q': '能否在 Docker 中运行 WorkAMA？',
    'help.faq.049.a': '仓库 compose 栈使用 workama 项目名与稳定的服务前缀。',
    'help.faq.050.q': '如何检查已安装版本？',
    'help.faq.050.a': '设置与公共平台界面暴露部署使用的当前产品/运行时契约。',
