    'help.faq.001.a': 'Open Chat and choose New conversation or one of the starter prompts.',
    'help.faq.002.q': 'Can I attach a file to a conversation?',
    'help.faq.002.a': 'Use the attachment control in the composer. Files are scanned, parsed, and scoped to the session.',
    'help.faq.003.q': 'Why is the send button disabled?',
    'help.faq.003.a': 'The realtime agent connection must be ready and the message must contain text.',
    'help.faq.004.q': 'How do I pause an agent run?',
    'help.faq.004.a': 'Use Pause in the conversation toolbar. The current event position is retained for resume.',
    'help.faq.005.q': 'What does an approval card mean?',
    'help.faq.005.a': 'A tool call crossed a workspace policy boundary and needs an explicit decision.',
    'help.faq.006.q': 'Where can I see citations?',
    'help.faq.006.a': 'Grounding sources appear with the assistant response when retrieval is used.',
    'help.faq.007.q': 'How do I retry a failed response?',
    'help.faq.007.a': 'Open the conversation again and use the retry action on the failed message or run.',
    'help.faq.008.q': 'Can I export a conversation?',
    'help.faq.008.a': 'Create or share an artifact from the conversation when the workspace policy permits it.',
    'help.faq.009.q': 'Why does the assistant say a source is untrusted?',
    'help.faq.009.a': 'External content is marked as untrusted so it cannot change system instructions or permissions.',
    'help.faq.010.q': 'How are usage limits shown?',
    'help.faq.010.a': 'The conversation toolbar shows steps used against the session budget.',
    'help.faq.011.q': 'How do I create a knowledge base?',
    'help.faq.011.a': 'Open Knowledge and choose New knowledge base, then add source files.',
    'help.faq.012.q': 'Which files can be indexed?',
    'help.faq.012.a': 'Supported formats are validated by the API and rejected with a clear format error when unsupported.',
    'help.faq.013.q': 'How do I check indexing progress?',
    'help.faq.013.a': 'The knowledge list and document table expose the current parsing and indexing status.',
    'help.faq.014.q': 'Can I search a single knowledge base?',
    'help.faq.014.a': 'Open the knowledge base detail view and use the retrieval playground.',
    'help.faq.015.q': 'How are documents isolated?',
    'help.faq.015.a': 'Documents are workspace scoped and every retrieval request is checked against the actor workspace.',
    'help.faq.016.q': 'What is the retrieval playground for?',
    'help.faq.016.a': 'It lets you inspect exact matching chunks before they are used to ground an AMA response.',
    'help.faq.017.q': 'How do I remove a source?',
    'help.faq.017.a': 'Use the document action menu or the dataset API; deletion is subject to retention policy.',
    'help.faq.018.q': 'How is retrieval quality measured?',
    'help.faq.018.a': 'Evaluation sets can be run from Knowledge evaluation to compare retrieval quality over time.',
    'help.faq.019.q': 'Can I sync a connector?',
    'help.faq.019.a': 'Connector setup is available from Studio integrations with explicit scopes and delivery history.',
    'help.faq.020.q': 'Why is a document marked failed?',
    'help.faq.020.a': 'The document parser or malware/format validation failed; the document error is retained for diagnosis.',
    'help.faq.021.q': 'How do I create a workflow?',
    'help.faq.021.a': 'Open Workflows, define the graph, and save a version before running it.',
    'help.faq.022.q': 'What is a workflow version?',
    'help.faq.022.a': 'A version freezes the graph and policy-relevant configuration used by a run.',
    'help.faq.023.q': 'Can a workflow wait for approval?',
    'help.faq.023.a': 'Yes. A run enters pending approval when a governed action requires a reviewer.',
    'help.faq.024.q': 'Where do I see workflow runs?',
    'help.faq.024.a': 'Use the workflow run view or Platform operations for execution evidence.',
    'help.faq.025.q': 'How are retries handled?',
    'help.faq.025.a': 'Retryable external work is recorded with idempotency and retry state in the worker.',
    'help.faq.026.q': 'Can workflows call tools?',
    'help.faq.026.a': 'Tools are available through the configured capability set and remain subject to policy checks.',
    'help.faq.027.q': 'What happens when a workflow fails?',
    'help.faq.027.a': 'The run records status, error, trace data, and an operational event for diagnosis.',
    'help.faq.028.q': 'Can I publish an app from a workflow?',
    'help.faq.028.a': 'Studio apps can be published only after the required review and version checks pass.',
    'help.faq.029.q': 'How do automations differ from workflows?',
    'help.faq.029.a': 'Automations trigger work on schedules or events; workflows describe the executable graph.',
    'help.faq.030.q': 'How do I stop a queued run?',
    'help.faq.030.a': 'Cancel it from the run control surface before the worker claims execution.',
    'help.faq.031.q': 'Which roles can approve tool calls?',
    'help.faq.031.a': 'The workspace authorization policy decides which roles can approve each risk level.',
    'help.faq.032.q': 'Where are audit events stored?',
    'help.faq.032.a': 'Enterprise audit events are available to authorized administrators and carry request context.',
    'help.faq.033.q': 'How do I configure SSO?',
    'help.faq.033.a': 'Open Enterprise identity in the console and configure the allowlisted identity provider.',
    'help.faq.034.q': 'Are API keys stored in plain text?',
    'help.faq.034.a': 'No. Keys are hashed and displayed only at creation time.',
    'help.faq.035.q': 'How are provider credentials protected?',
    'help.faq.035.a': 'Credentials are encrypted or stored by reference and are never returned in list responses.',
    'help.faq.036.q': 'Can I revoke a device session?',
    'help.faq.036.a': 'Administrators can review and revoke device sessions from Security and Devices.',
    'help.faq.037.q': 'How do privacy requests work?',
    'help.faq.037.a': 'Privacy requests create an auditable workflow with processing steps and deletion tombstones.',
    'help.faq.038.q': 'Does WorkAMA train on customer content?',
    'help.faq.038.a': 'The public platform contract reports customer content training as disabled.',
    'help.faq.039.q': 'How do I report a security issue?',
    'help.faq.039.a': 'Use the security contact in the repository security policy and include a reproducible request ID where possible.',
    'help.faq.040.q': 'Where can I review usage and billing?',
    'help.faq.040.a': 'Gateway usage and Billing show current limits, balances, and subscription state.',
    'help.faq.041.q': 'What does a request ID identify?',
    'help.faq.041.a': 'It links a response and its operational logs without exposing secrets or customer content.',
    'help.faq.042.q': 'How do I use the API?',
    'help.faq.042.a': 'Read the API docs, create a scoped credential, and send the request with workspace authorization.',
    'help.faq.043.q': 'Is there a WebSocket session API?',
    'help.faq.043.a': 'Yes. Session tickets authorize a short-lived realtime connection for one session.',
    'help.faq.044.q': 'How do webhooks retry?',
    'help.faq.044.a': 'Delivery state records attempts, response codes, signatures, and the next retry time.',
    'help.faq.045.q': 'How do I inspect gateway logs?',
    'help.faq.045.a': 'Authorized operators can open Gateway logs and filter by channel, status, or request ID.',
    'help.faq.046.q': 'What does status operational mean?',
    'help.faq.046.a': 'The corresponding health endpoint returned a successful response within the check timeout.',
    'help.faq.047.q': 'How do I contact support?',
    'help.faq.047.a': 'Use the platform support entry with the workspace, request ID, and a minimal reproduction.',
    'help.faq.048.q': 'Where are release notes maintained?',
    'help.faq.048.a': 'The repository release documents and the current progress tracker record shipped platform changes.',
    'help.faq.049.q': 'Can I run WorkAMA in Docker?',
    'help.faq.049.a': 'The repository compose stack uses the workama project name and stable service prefixes.',
    'help.faq.050.q': 'How do I check the installed version?',
    'help.faq.050.a': 'The setup and public platform surfaces expose the current product/runtime contract used by the deployment.',
