export type MessageKey = keyof typeof messages['en-US']

export function translate(locale: Locale, key: MessageKey): string {
  return messages[locale][key] ?? messages['en-US'][key] ?? key
}

export function getInitialLocale(browserLocale?: string | null): Locale {
  // 默认中文（产品主语言）。仅当浏览器显式偏好英文时才回退 en-US，
  // 解决「默认应该显示中文」的需求，并让未设置偏好的用户始终看到中文界面。
  return browserLocale?.toLowerCase().startsWith('en') ? 'en-US' : 'zh-CN'
}
